#include <cuda_runtime.h>

__global__ void parallelBinarySearch(int* d_elements, int target, int segment_size, bool* d_found) {
    int threadId = blockIdx.x * blockDim.x + threadIdx.x;
    int start = threadId * segment_size;
    int end = start + segment_size - 1;

    // Ensure that the segment is within the bounds of the array
    if (start >= N || end >= N) {
        return;
    }

    int low = start, high = end;
    while(low <= high) {
        int mid = low + (high - low) / 2;
        if(d_elements[mid] == target) {
            // Use atomic operation to safely set d_found to true
            atomicOr(d_found, true);
            return;
        }
        if(d_elements[mid] < target)
            low = mid + 1;
        else
            high = mid - 1;
    }
}

int main() {
    int N = 1024; // Example size of the array
    int target = 42; // Example target value
    int segment_size = 32; // Example segment size

    int* d_elements; // device pointer to the array of elements
    bool* d_found; // device pointer to a boolean variable indicating whether the element is found

    // Allocate memory on the device
    cudaMalloc(&d_elements, N * sizeof(int));
    cudaMalloc(&d_found, sizeof(bool));

    // Initialize d_found to false
    cudaMemset(d_found, 0, sizeof(bool));

    // ... (data transfer to d_elements)

    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;
    parallelBinarySearch<<<blocksPerGrid, threadsPerBlock>>>(d_elements, target, segment_size, d_found);

    // Retrieve results
    bool found;
    cudaMemcpy(&found, d_found, sizeof(bool), cudaMemcpyDeviceToHost);

    // Clean up
    cudaFree(d_elements);
    cudaFree(d_found);

    // Output result
    if (found) {
        printf("Element found.\n");
    } else {
        printf("Element not found.\n");
    }

    return 0;
}
